          ex.km_per_l = pyRoundN(km / accL, 2); ex.l_per_100km = pyRoundN(accL * 100 / km, 2);
          ex.cost_per_km = pyRoundN(accCost / km, 1); ex.interval_km = pyRoundN(km, 1); ex.interval_liters = pyRoundN(accL, 2);
          intervals.push({ log_id: r.id, logged_at: r.logged_at, km, liters: accL, cost: accCost, ac: accAc });
