    const totals = periodTotals(c, lo, hi);
    const liters = sel.reduce((a, l) => a + (l.liters || 0), 0), paidWithLiters = sel.reduce((a, l) => a + (l.liters ? l.amount : 0), 0);
    const rows = sel.slice().reverse().map((l) => Object.assign({}, l, extras[l.id]));
    const monthly = buildSeries(dailyRows(c, lo, hi), rng.chart_start, rng.chart_end, 'month', this.weekStart()).map((b) => ({ key: b.key, label: b.label, fuel: b.fuel }));
