      totals: { fuel_spent: totals.fuel, expenses: totals.expenses, fuel_pct: pct(totals.fuel, totals.expenses), liters: pyRoundN(liters, 2),
        avg_price_per_liter: liters ? r0(paidWithLiters / liters) : null, fill_ups: sel.length, logged_fuel_amount: sel.reduce((a, l) => a + l.amount, 0) },
      monthly, price_series: sel.filter((l) => extras[l.id].price_per_liter).map((l) => ({ date: l.logged_at.slice(0, 10), price: extras[l.id].price_per_liter })),
